def fill_patient_lab(apps, schema_editor):
    """Give existing patients a lab: the lab of the nurse who registered them (from the audit log),
    otherwise the lab of their first visit. Patients with neither stay without a lab (admin only)."""
    Patient = apps.get_model("clinic", "Patient")
    SystemLog = apps.get_model("clinic", "SystemLog")
    Visit = apps.get_model("clinic", "Visit")
    for patient in Patient.objects.filter(lab__isnull=True):
        log = (SystemLog.objects.filter(action="CREATE_PATIENT", description=f"patient_id={patient.pk}")
               .select_related("actor").order_by("logged_at").first())
        lab_id = log.actor.lab_id if log and log.actor_id else None
        if not lab_id:
            first = Visit.objects.filter(patient_id=patient.pk).order_by("id").first()
            lab_id = first.lab_id if first else None
        if lab_id:
            patient.lab_id = lab_id
            patient.save(update_fields=["lab"])


